namespace LSE.AutoCADElectrical.ProjectDoctor;
public static class DiagnosisService {
 public static Diagnosis Examine(string wdpPath,ProjectStandard std,DoctorRules r,bool checkDrawings,bool insertWdm,Action<string>? progress=null){
  if(!File.Exists(wdpPath))throw new FileNotFoundException("Project file was not found.",wdpPath);wdpPath=Path.GetFullPath(wdpPath);
  if(wdpPath.Equals(std.WdpPath,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("That is the LSE template itself. Pick a project to examine, not the standard.");
  var dx=new Diagnosis{WdpPath=wdpPath,Standard=std,Rules=r,DrawingsChecked=checkDrawings};void Log(string m){dx.Log.Add(m);progress?.Invoke(m);}
  Log($"Examining {wdpPath}");Log($"Standard: {std.WdpPath}{(std.Bundled?" (bundled copy)":"")}");Log("Rules: "+r.Source);
  var wdp=TextFileService.Read(wdpPath);Log($"Project file: {wdp.Lines.Count} line(s), {TextFileService.EncodingName(wdp.Encoding)}");
  Descriptions(dx,wdp,Log);Lines(dx,wdp,'+',"Library and menu paths","Project options",std.Options,r.EnforceOptions,r.ProtectedOptions,Log);Lines(dx,wdp,'?',null,"Project properties",std.Properties,r.EnforceProperties,r.ProtectedProperties,Log);
  Mapping(dx,Log);Labels(dx,Log);Configuration(dx,Log);Drawings(dx,wdp,checkDrawings,insertWdm,Log);
  foreach(var f in dx.Findings)f.Selected=f.Recommended;Log($"Result: {dx.Status}; {dx.Findings.Count} finding(s), {dx.Recommended} recommended repair(s)");return dx;}
 static void Add(Diagnosis dx,Finding f){dx.Findings.Add(f);}
 static void Descriptions(Diagnosis dx,TextDocument wdp,Action<string> log){var r=dx.Rules;var std=dx.Standard;int count=r.DescriptionLineCount>0?r.DescriptionLineCount:(std.Descriptions.Count==0?0:std.Descriptions.Keys.Max());int ok=0;
  for(int i=1;i<=count;i++){string? cur=TextFileService.Get(wdp,'*',i);string placeholder=std.Descriptions.TryGetValue(i,out var p)?p:"";string item=StandardService.Label(r,std,'*',i);
   if(cur is null)Add(dx,new Finding{Category="Project descriptions",Item=item,Current="(line missing)",Standard=placeholder,Severity=Severity.Error,Action=RepairAction.Add,Recommended=true,Target="wdp",Prefix='*',Index=i,Value=r.FillBlankDescriptionsWithPlaceholder?placeholder:"",Note="The Project Manager description dialog has no line "+i+" for this project."});
   else if(cur.Trim().Length==0&&placeholder.Trim().Length>0)Add(dx,new Finding{Category="Project descriptions",Item=item,Current="(blank)",Standard=placeholder,Severity=Severity.Info,Action=RepairAction.Replace,Recommended=false,Target="wdp",Prefix='*',Index=i,Value=placeholder,Note="Blank is allowed. Tick to put the template placeholder text in so the engineer sees what belongs here."});
   else ok++;}
  log($"Project descriptions: {ok}/{count} present");}
 static void Lines(Diagnosis dx,TextDocument wdp,char prefix,string? pathCategory,string category,SortedDictionary<int,string> template,bool enforce,List<int> prot,Action<string> log){var r=dx.Rules;var std=dx.Standard;int ok=0;
  foreach(var (idx,tv) in template){bool isList=prefix=='+'&&r.PathListOptions.Contains(idx);bool isPath=prefix=='+'&&r.PathOptions.Contains(idx);string cat=(isList||isPath)&&pathCategory is not null?pathCategory:category;bool locked=prot.Contains(idx);string item=StandardService.Label(r,std,prefix,idx);string? cur=TextFileService.Get(wdp,prefix,idx);
   if(cur is null){Add(dx,new Finding{Category=cat,Item=item,Current="(line missing)",Standard=tv,Severity=locked?Severity.Info:Severity.Error,Action=RepairAction.Add,Recommended=!locked,Target="wdp",Prefix=prefix,Index=idx,Value=tv,Note=locked?"Protected by the rules JSON; left for you to decide.":"AutoCAD Electrical falls back to its built-in default for a missing line."});continue;}
   bool same=isList?(r.Merge?TextFileService.StartsWithPathList(cur,tv):TextFileService.SamePathList(cur,tv)):isPath?TextFileService.SamePath(cur,tv):cur.Trim().Equals(tv.Trim(),StringComparison.Ordinal);
   if(same){ok++;continue;}string value=isList&&r.Merge?TextFileService.MergePathList(cur,tv):tv;
   Add(dx,new Finding{Category=cat,Item=item,Current=cur,Standard=tv,Severity=locked?Severity.Info:Severity.Warning,Action=RepairAction.Replace,Recommended=enforce&&!locked,Target="wdp",Prefix=prefix,Index=idx,Value=value,Note=locked?"Protected by the rules JSON; left for you to decide.":isList&&r.Merge?"Merge mode: template paths first, then the project's extra paths.":enforce?"Differs from the standard.":"Differs from the standard. Enforcement is off in the rules JSON; tick to replace."});}
  foreach(var (idx,cur) in TextFileService.Group(wdp,prefix))if(!template.ContainsKey(idx))Add(dx,new Finding{Category=category,Item=StandardService.Label(r,std,prefix,idx),Current=cur,Standard="(not in the standard)",Severity=Severity.Info,Action=RepairAction.None,Target="wdp",Prefix=prefix,Index=idx,Note="The template has no such line; left unchanged."});
  log($"{category} ({prefix}[n]): {ok}/{template.Count} match the standard");}
 static void Mapping(Diagnosis dx,Action<string> log){var r=dx.Rules;var std=dx.Standard;const string cat="Title block mapping (.wdt)";if(std.Wdt is null){log("Title block mapping: the standard has no .wdt; check skipped");return;}
  string want=TextFileService.MappingPath(dx.WdpPath);string? path=TextFileService.ExistingCaseInsensitive(want);
  if(path is null){Add(dx,new Finding{Category=cat,Item=Path.GetFileName(want),Current="(file missing)",Standard=Path.GetFileName(std.Wdt.Path),Severity=r.RequireMappingFile?Severity.Error:Severity.Info,Action=RepairAction.CreateFile,Recommended=r.RequireMappingFile,Target="wdt",Note="Without it Title Block Update cannot map the project description lines, sheet values and drawing descriptions to the LSE title block. A copy of the template file is created."});log("Title block mapping: file missing");return;}
  var doc=TextFileService.Read(path);var maps=TextFileService.Mappings(doc);int ok=0;var tb=maps.FirstOrDefault(m=>m.IsBlock);var stdBlock=std.Mappings.FirstOrDefault(m=>m.IsBlock);
  if(stdBlock is not null){if(tb is null)Add(dx,new Finding{Category=cat,Item="BLOCK",Current="(missing)",Standard=stdBlock.Code,Severity=Severity.Error,Action=RepairAction.Add,Recommended=true,Target="wdt",Value=stdBlock.Code,Note="The BLOCK line names the title block(s) the mapping applies to."});
   else{var have=TextFileService.BlockNames(tb.Code);var missing=TextFileService.BlockNames(stdBlock.Code).Where(w=>!have.Any(h=>h.Equals(w,StringComparison.OrdinalIgnoreCase))).ToList();if(missing.Count==0)ok++;else Add(dx,new Finding{Category=cat,Item="BLOCK",Current=tb.Code,Standard=stdBlock.Code,Severity=Severity.Warning,Action=RepairAction.Replace,Recommended=r.EnforceMappings,Target="wdt",Value=string.Join(",",have.Concat(missing)),Note="The LSE title block name is added; existing names are kept."});}}
  foreach(var sm in std.Mappings.Where(m=>!m.IsBlock)){var pm=maps.FirstOrDefault(m=>!m.IsBlock&&m.Attribute.Equals(sm.Attribute,StringComparison.OrdinalIgnoreCase));
   if(pm is null)Add(dx,new Finding{Category=cat,Item=sm.Attribute,Current="(missing)",Standard=sm.Code,Severity=Severity.Error,Action=RepairAction.Add,Recommended=true,Target="wdt",Value=sm.Code,Note="Title block attribute "+sm.Attribute+" is not filled by Title Block Update."});
   else if(!pm.Code.Equals(sm.Code,StringComparison.OrdinalIgnoreCase))Add(dx,new Finding{Category=cat,Item=sm.Attribute,Current=pm.Code,Standard=sm.Code,Severity=Severity.Warning,Action=RepairAction.Replace,Recommended=r.EnforceMappings,Target="wdt",Value=sm.Code,Note=r.EnforceMappings?"Differs from the standard.":"Differs from the standard. Enforcement is off in the rules JSON; tick to replace."});
   else ok++;}
  foreach(var pm in maps.Where(m=>!m.IsBlock&&!std.Mappings.Any(s=>s.Attribute.Equals(m.Attribute,StringComparison.OrdinalIgnoreCase))))Add(dx,new Finding{Category=cat,Item=pm.Attribute,Current=pm.Code,Standard="(not in the standard)",Severity=Severity.Info,Action=RepairAction.None,Target="wdt",Note="Extra mapping; left unchanged."});
  log($"Title block mapping: {ok}/{std.Mappings.Count} match the standard ({path})");}
 static void Labels(Diagnosis dx,Action<string> log){var r=dx.Rules;var std=dx.Standard;const string cat="Description labels (.wdl)";if(std.Wdl is null){log("Description labels: the standard has no _wdtitle.wdl; check skipped");return;}
  string want=TextFileService.LabelsPath(dx.WdpPath);string? path=TextFileService.ExistingCaseInsensitive(want);
  if(path is null){Add(dx,new Finding{Category=cat,Item=Path.GetFileName(want),Current="(file missing)",Standard=Path.GetFileName(std.Wdl.Path),Severity=r.RequireLabelFile?Severity.Error:Severity.Info,Action=RepairAction.CreateFile,Recommended=r.RequireLabelFile,Target="wdl",Note="Without it the Project Manager description dialog shows LINE1, LINE2 ... instead of PROJECT NAME, QUOTE# ... A copy of the template file is created."});log("Description labels: file missing");return;}
  var doc=TextFileService.Read(path);var labels=TextFileService.Labels(doc);int ok=0;
  foreach(var (idx,sl) in std.Labels){if(!labels.TryGetValue(idx,out var pl))Add(dx,new Finding{Category=cat,Item="LINE"+idx,Current="(missing)",Standard=sl,Severity=Severity.Error,Action=RepairAction.Add,Recommended=true,Target="wdl",Index=idx,Value=sl});
   else if(!pl.Trim().Equals(sl.Trim(),StringComparison.OrdinalIgnoreCase))Add(dx,new Finding{Category=cat,Item="LINE"+idx,Current=pl,Standard=sl,Severity=Severity.Warning,Action=RepairAction.Replace,Recommended=r.EnforceLabels,Target="wdl",Index=idx,Value=sl,Note=r.EnforceLabels?"Differs from the standard.":"Differs from the standard. Enforcement is off in the rules JSON; tick to replace."});
   else ok++;}
  foreach(var (idx,pl) in labels)if(!std.Labels.ContainsKey(idx))Add(dx,new Finding{Category=cat,Item="LINE"+idx,Current=pl,Standard="(not in the standard)",Severity=Severity.Info,Action=RepairAction.None,Target="wdl",Index=idx,Note="Extra label; left unchanged."});
  log($"Description labels: {ok}/{std.Labels.Count} match the standard ({path})");}
 static void Configuration(Diagnosis dx,Action<string> log){var r=dx.Rules;string want=TextFileService.ConfigurationPath(dx.WdpPath);string? path=TextFileService.ExistingCaseInsensitive(want);
  if(path is not null){log("Project configuration (.aepx): present");return;}
  Add(dx,new Finding{Category="Project configuration (.aepx)",Item=Path.GetFileName(want),Current="(file missing)",Standard="one per project",Severity=r.RequireProjectConfigurationFile?Severity.Error:Severity.Info,Action=RepairAction.CreateFile,Recommended=r.RequireProjectConfigurationFile,Target="aepx",Note="AutoCAD Electrical 2024 and later writes this file itself when the project is opened, so it is normally safe to leave. Tick to create a minimal one now."});log("Project configuration (.aepx): missing");}
 static void Drawings(Diagnosis dx,TextDocument wdp,bool check,bool insertWdm,Action<string> log){var r=dx.Rules;var std=dx.Standard;const string cat="Drawings";dx.Drawings=TextFileService.Drawings(wdp);
  if(dx.Drawings.Count==0){Add(dx,new Finding{Category=cat,Item="(project drawing list)",Current="no drawings",Standard="at least one drawing",Severity=Severity.Info,Action=RepairAction.None,Note="The project lists no drawings. Add them in the Project Manager."});log("Drawings: none listed");return;}
  int missing=0,ok=0,skipped=0;string wdm=r.WdmBlockName;string tbNames=string.Join(", ",std.TitleBlockNames);DrawingInspection? tpl=null;
  if(check&&!r.CheckWireLayers)log("Wire layers: checkWireLayers is false in the rules JSON; check skipped");
  if(check&&r.CheckWireLayers){if(std.TemplateDrawingPath.Length==0)log("Wire layers: no template drawing next to the standard .wdp; check skipped");
   else{tpl=DrawingInspectionService.Inspect(std.TemplateDrawingPath,wdm,std.TitleBlockNames);if(tpl.OpenInEditor||tpl.Error.Length>0){log("Wire layers: template drawing "+(tpl.OpenInEditor?"is open in the editor":"could not be read: "+tpl.Error)+"; check skipped");tpl=null;}
    else{dx.TemplateDrawing=tpl;var names=WireLayerService.WireLayers(tpl,r);log($"Wire layers: standard is {Path.GetFileName(tpl.Path)} with {names.Count} wire layer(s): {string.Join(", ",names)}; WIRELAYS = \"{tpl.Wdm("WIRELAYS")}\"");}}}
  foreach(var e in dx.Drawings){string full=TextFileService.FullPath(dx.WdpPath,e);
   if(!File.Exists(full)){missing++;Add(dx,new Finding{Category=cat,Item=e.Path,Current="(file not found)",Standard="file on disk",Severity=Severity.Warning,Action=RepairAction.RemoveDrawing,Recommended=false,Target="wdp",Value=full,Index=e.PathLine,Note="Listed in the project but missing on disk: "+full+". Restore the file, or tick to drop it from the project list."});continue;}
   if(!check){skipped++;continue;}log("Inspecting "+e.Path);var i=DrawingInspectionService.Inspect(full,wdm,std.TitleBlockNames);
   if(i.OpenInEditor){skipped++;dx.OpenDrawings++;Add(dx,new Finding{Category=cat,Item=e.Path,Current="open in the editor",Standard="closed",Severity=Severity.Info,Action=RepairAction.None,Target=full,Note="Not inspected while open in AutoCAD. The doctor never writes to an open drawing. Close it (the project stays active) and press Examine again."});continue;}
   if(i.Error.Length>0){skipped++;Add(dx,new Finding{Category=cat,Item=e.Path,Current="could not be read",Standard="readable DWG",Severity=Severity.Info,Action=RepairAction.None,Target=full,Note=i.Error});continue;}
   bool good=true;
   if(!i.HasWdm){good=false;bool canInsert=std.TemplateDrawingPath.Length>0;Add(dx,new Finding{Category=cat,Item=e.Path,Current="no "+wdm+" block",Standard=wdm+" block (AutoCAD Electrical drawing settings)",Severity=Severity.Error,Action=RepairAction.InsertWdm,Recommended=insertWdm&&canInsert,Target=full,Value=std.TemplateDrawingPath,Note=canInsert?"Copies the "+wdm+" block and its values from "+Path.GetFileName(std.TemplateDrawingPath)+" into model space.":"No template drawing with a "+wdm+" block is available next to the standard .wdp; open the drawing and use Drawing Properties to add it."});}
   if(std.TitleBlockNames.Count>0&&i.TitleBlocks.Count==0){good=false;Add(dx,new Finding{Category=cat,Item=e.Path,Current="no LSE title block",Standard=tbNames,Severity=Severity.Warning,Action=RepairAction.None,Target=full,Note="Layouts: "+string.Join(", ",i.Layouts)+". Insert the LSE title block from the template drawing by hand; the doctor does not place title blocks."});}
   if(tpl is not null)WireLayers(dx,e,full,i,tpl,ref good);
   if(good)ok++;}
  log(check?$"Drawings: {dx.Drawings.Count} listed, {ok} pass, {missing} missing on disk, {skipped} not inspected":$"Drawings: {dx.Drawings.Count} listed, {missing} missing on disk (DWG contents not checked)");}
 static void WireLayers(Diagnosis dx,WdpDrawingEntry e,string full,DrawingInspection i,DrawingInspection tpl,ref bool good){var r=dx.Rules;const string catA="Wire layer settings (WD_M)";const string catL="Wire layers";string tplName=Path.GetFileName(tpl.Path);
  if(i.HasWdm)foreach(string tag in r.WireLayerAttributes){if(!tpl.WdmValues.TryGetValue(tag,out var tv))continue;string item=e.Path+" : "+tag;
   if(!i.WdmValues.TryGetValue(tag,out var cur)){good=false;Add(dx,new Finding{Category=catA,Item=item,Name=tag,Current="(attribute missing)",Standard=tv,Severity=Severity.Warning,Action=RepairAction.None,Target=full,Note="This drawing's "+r.WdmBlockName+" block is older and has no "+tag+" attribute. In AutoCAD Electrical use Project > Other Tools > Update to New WD_M Block (keep values), then examine again."});continue;}
   if(WireLayerService.SameValue(r,tag,cur,tv))continue;good=false;
   Add(dx,new Finding{Category=catA,Item=item,Name=tag,Current=cur.Trim().Length==0?"(blank = every layer)":cur,Standard=tv,Severity=Severity.Warning,Action=RepairAction.SetAttribute,Recommended=r.EnforceWireLayers,Target=full,Value=tv,Note=(WireLayerService.IsList(r,tag)?"Comma-delimited list of the layers AutoCAD Electrical treats as wires (wildcards allowed). ":"Layer name AutoCAD Electrical uses for this purpose. ")+(r.EnforceWireLayers?"Set to the template value.":"Enforcement is off in the rules JSON; tick to set the template value.")});}
  var tplWire=new HashSet<string>(WireLayerService.WireLayers(tpl,r),StringComparer.OrdinalIgnoreCase);
  foreach(string name in tplWire){var t=tpl.Layer(name)!;var d=i.Layer(name);string item=e.Path+" : "+name;
   if(d is null){good=false;Add(dx,new Finding{Category=catL,Item=item,Name=name,Current="(layer missing)",Standard=t.Summary,Severity=Severity.Error,Action=RepairAction.CreateLayer,Recommended=true,Target=full,Value=tpl.Path,Note="Wire layer of the template drawing. It is copied from "+tplName+" with its linetype and AutoCAD Electrical wire-type data."});continue;}
   var diff=WireLayerService.Differences(d,t,r);if(diff.Count==0)continue;good=false;
   Add(dx,new Finding{Category=catL,Item=item,Name=name,Current=d.Summary+(WireLayerService.HasWireXdata(d,r)?"":", no wire-type data"),Standard=t.Summary,Severity=Severity.Warning,Action=RepairAction.RepairLayer,Recommended=r.EnforceWireLayers,Target=full,Value=tpl.Path,Note="Differs from "+tplName+": "+string.Join("; ",diff)+". Color, linetype, lineweight, plot flag and wire-type data are set from the template; whatever is drawn on the layer stays."});}
  foreach(string name in WireLayerService.WireLayers(i,r)){if(WireLayerService.IsStandard(name,tpl,r,tplWire)||r.NeverPurgeLayers.Any(x=>x.Equals(name,StringComparison.OrdinalIgnoreCase)))continue;var d=i.Layer(name)!;string item=e.Path+" : "+name;good=false;
   if(d.EntityCount==0)Add(dx,new Finding{Category=catL,Item=item,Name=name,Current="unused wire layer, nothing drawn on it ("+d.Summary+")",Standard="(not in the template)",Severity=Severity.Warning,Action=RepairAction.PurgeLayer,Recommended=r.PurgeUnusedWireLayers,Target=full,Note="Flagged as a wire layer (matches WIRELAYS or carries wire-type data) but the template has no such layer and nothing uses it. Purging removes it from the layer list."});
   else Add(dx,new Finding{Category=catL,Item=item,Name=name,Current=d.EntityCount+" entities on a non-standard wire layer ("+d.Summary+")",Standard="(not in the template)",Severity=Severity.Warning,Action=RepairAction.None,Target=full,Note="Move the entities to a standard wire layer (or add the layer to the template drawing), then examine again to purge it. The doctor does not move entities."});}
  if(i.HasWdm)foreach(string tag in r.WireLayerAttributes){string v=i.Wdm(tag);if(!WireLayerService.SameValue(r,tag,v,tpl.Wdm(tag)))continue;
   foreach(string n in WireLayerService.IsList(r,tag)?WireLayerService.Split(v):v.Trim().Length>0?new List<string>{v.Trim()}:new()){if(WireLayerService.HasWildcard(n)||i.Layer(n) is not null||tplWire.Contains(n))continue;
    Add(dx,new Finding{Category=catA,Item=e.Path+" : "+tag+" -> "+n,Name=tag,Current="names layer "+n+", which does not exist",Standard="layer present",Severity=Severity.Info,Action=RepairAction.None,Target=full,Note="The template lists the same name but its "+tplName+" has no such layer, so there is nothing to copy. Create it by hand or fix the template drawing."});}}}
 public static string Render(Diagnosis dx){var x=new List<string>{"LSE_Doctor report","Project: "+dx.WdpPath,"Examined: "+dx.Examined.ToString("s")+" by "+Environment.UserName,"Standard: "+dx.Standard.WdpPath+(dx.Standard.Bundled?" (bundled copy)":""),"Rules: "+dx.Rules.Source,"Status: "+dx.Status+(dx.DrawingsChecked?"":" (drawing contents not checked)"),""};
  foreach(var g in dx.Findings.GroupBy(f=>f.Category)){x.Add("== "+g.Key);foreach(var f in g)x.Add($"  [{f.Severity}] {f.Item}: {Short(f.Current)}  ->  standard: {Short(f.Standard)}  |  {f.ActionText}{(f.Recommended?" (recommended)":"")}{(f.Note.Length>0?"  |  "+f.Note:"")}");x.Add("");}
  x.Add("== Checks");x.AddRange(dx.Log.Select(l=>"  "+l));return string.Join(Environment.NewLine,x);}
 public static string Short(string v,int max=160){v=v.Replace("\r"," ").Replace("\n"," ");return v.Length<=max?v:v[..max]+"...";}
}
